def squash(s: str) -> str:
    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        j = i + 1
        while j < n and s[j] == char:
            j += 1

        escaped = "\\" + char if char == "\\" or "0" <= char <= "9" else char
        run_length = j - i

        if run_length >= 3:
            result.append(str(run_length))
            result.append(escaped)
        else:
            result.append(escaped * run_length)

        i = j

    return "".join(result)
